custom_css:
/* IMPORT FONT */
@import url("https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600&family=Plus+Jakarta+Sans:wght@600&family=Poppins:wght@500&display=swap");


:root{--white:#fff;--black:#111;--body:#474747;--heading:#1c1c1c;--pink:#e01783;--blue:#00758d;--purple:#773dbe;--dark:#161a29;--light:#f6f6f6;--font-body:Inter, Arial, sans-serif;--font-heading:"Plus Jakarta Sans", Arial, sans-serif;--container:1200px;--radius:12px;}


h1, h2, h3{font-family:var(--font-heading);color:var(--heading);margin:0;}
h1{font-size:clamp(30px, 4vw, 55px)!important;line-height:1.16;font-weight:500;}
h2{font-size:clamp(24px, 3vw, 40px)!important;line-height:1.25;font-weight:500;}
h3{font-size:24px!important;line-height:1.65;font-weight:600;}
.section-dark h1, .section-dark h2, .section-dark h3{color:var(--white);}

/* COMMON CSS USED ON ALL PAGES */
*{box-sizing:border-box;}
html{scroll-behavior:smooth;}
body{margin:0;color:var(--body);font:400 16px/1.75 var(--font-body);background:var(--white);}
img{display:block;}
a{text-decoration:none;}
button{font:inherit;}
.container{width:min(var(--container), calc(100% - 40px));margin-inline:auto;}
.section-padding{padding:80px 0;}
.bg-white{background:var(--white);}
.bg-light{background:var(--light);}
.section-dark{background:var(--dark);color:var(--white);overflow:hidden;position:relative;}
.section-dark:before, .section-dark:after{content:"";position:absolute;border-radius:50%;filter:blur(50px);pointer-events:none;}
.section-dark:before{width:400px;height:400px;background:rgba(119, 61, 190, .12);left:-70px;top:-70px;}
.section-dark:after{width:600px;height:600px;background:rgba(224, 23, 131, .12);right:2%;top:0;}
.section-dark>.container{position:relative;z-index:1;}
.txt-pink{color:var(--pink);}
p{margin:0;}
.eyebrow{font-size:18px;line-height:1.5;font-weight:500;margin-bottom:12px;}
.theme-btn{display:inline-flex;align-items:center;justify-content:flex-end;gap:12px;padding:7px 7px 7px 20px;border-radius:var(--radius);color:#fff;font-weight:500;line-height:1.2;}
.section-heading{margin-bottom:38px;}
.section-heading.left img{margin-left:240px;width:135px;}
.trust-strip{background:var(--blue);color:#fff;padding:40px 0;position:relative;overflow:hidden;}
.trust-strip::after{content:"";position:absolute;width:115px;height:94px;right:0;top:50%;transform:translateY(-50%);background:url("https://res.cloudinary.com/cgibjxmm/image/upload/v1785916237/custom-cms/trust-strip-flower.png") center/contain no-repeat;opacity:.08;pointer-events:none;}
.trust-strip .container{position:relative;z-index:1;}
.trust-item{display:flex;align-items:center;gap:15px;font-size:20px;line-height:1.4;}
.decorative-right{position:relative;overflow:hidden;}
.decorative-right:after, .decorative-right-top:after{content:"";position:absolute;width:415px;height:415px;background:url("https://res.cloudinary.com/cgibjxmm/image/upload/v1785916241/custom-cms/yoga-girl-background.png") center/contain no-repeat;right:0;bottom:0;pointer-events:none;}
.decorative-left{position:relative;overflow:hidden;}
.decorative-left:before{content:"";position:absolute;width:400px;height:414px;left:0;top:0;background:url("https://res.cloudinary.com/cgibjxmm/image/upload/v1785916220/custom-cms/hosting-event-background.png") center/contain no-repeat;}
.check-list{list-style:none;margin:0 0 32px;padding:0;display:grid;gap:20px;}
.devices{position:relative;}
.devices .laptop{width:692px;margin-left:auto;}
.devices .phone{position:absolute;left:0;bottom:0;width:158px;z-index:2;}
.page-banner{padding:80px 0;display:grid;place-items:center;text-align:center;isolation:isolate;}
.page-banner .container{position:relative;z-index:2;}
.page-banner-art{position:absolute;z-index:0;width:614px;height:400px;left:50%;top:50%;transform:translate(-50%, -50%);object-fit:contain;opacity:.34;pointer-events:none;}
.page-banner h1{font-size:clamp(42px, 4vw, 55px)!important;}
.page-banner p{line-height:2;}
.gradient-divider{display:block;width:200px;height:2px;margin:28px auto 20px;border-radius:100px;background:linear-gradient(90deg, var(--blue) 0%, var(--pink) 50%, var(--purple) 100%);}
.section-heading-left{margin-bottom:28px;text-align:left;}
.section-heading-left h2{display:block;}
.section-heading-left img{width:155px;height:18px;margin:2px 0 0;object-fit:contain;}
.section-heading-left img.stroke-wide{width:225px;}
.content-split{position:relative;overflow:hidden;}
.content-split > .container, .decorative-left > .container, .pattern-right > .container{position:relative;z-index:1;}
.content-copy > p{line-height:2;}
.content-copy .theme-btn{margin-top:32px;}
.content-media{overflow:hidden;border-radius:var(--radius);}
.content-media img{width:100%;object-fit:cover;}
.content-media-wide img{height:370px;}
.content-figure{margin:0;}
.content-figure img{width:100%;height:251px;border-radius:var(--radius);object-fit:cover;}
.content-figure figcaption{margin-top:20px;color:var(--heading);font-size:20px;line-height:1.6;font-weight:500;}
.pattern-right{position:relative;overflow:hidden;}
.pattern-right::after{content:"";position:absolute;width:400px;height:414px;right:0;top:0;background:url("https://res.cloudinary.com/cgibjxmm/image/upload/v1785916220/custom-cms/hosting-event-background.png") center/contain no-repeat;pointer-events:none;}
.feature-cta{padding: 20px; border:1px solid var(--pink);border-radius:20px;display:flex;align-items:center;justify-content:space-between;}
.feature-cta-copy{display:flex;align-items:center;gap:20px;}
.feature-cta-copy > img{margin: 0;}
.feature-cta h2{color:var(--black);}
.inner-hero-title{font-family:"Poppins", sans-serif;font-size:55px;line-height:64px;font-weight:500;}
.inner-hero-title-accent{color:#E81A7B;}
.inner-hero-subtitle{font-family:"Inter", sans-serif;font-size:16px;line-height:32px;font-weight:400;color:var(--white);}
.inner-page-hero-bg{background-size:contain;background-position:center;background-repeat:no-repeat;background-color:#161a29;}
.about-banner{min-height:320px;padding:80px 0;background:#161a29!important;position:relative;overflow:hidden;isolation:isolate;}
.about-banner::before{width:214px;height:214px;left:-25px;top:69px;background:rgba(224,23,131,.12);filter:blur(50px);transform:scaleY(-1);}
.about-banner::after{width:209px;height:209px;left:auto;right:-27px;top:69px;background:rgba(119,61,190,.12);filter:blur(50px);}
.about-banner .page-banner-art{width:614px;height:400px;left:50%;top:50%;transform:translate(-50%,-50%);object-fit:contain;opacity:.34;z-index:0;}
.about-banner .container{position:relative;z-index:2;}
.theme-btn span{width:36px;height:36px;background:#fff;border-radius:12px;display:grid;place-items:center;flex:0 0 auto; color: var(--blue);}
.theme-btn span img{width:36px;height:36px;margin:0;}
.theme-btn-blue{background:var(--blue);}
.theme-btn-purple{background:var(--purple);}
.section-heading h2{display:inline-block;}
.section-heading img{width:155px;height:18px;object-fit:contain;}
.section-heading.text-center{display:flex; flex-direction:column; align-items:center; text-align:center;}
.section-heading.text-center h2{display:block;}
.section-heading.text-center > img{display:block; width:155px; height:18px; margin:2px auto 0; object-fit:contain;}
.hero{padding:80px 0;}
.hero-subtitle{font-size:20px;line-height:1.6;margin-top:24px;}
.hero-quote{line-height:2;margin-top:8px;}
.button-row{margin-top:24px;}
.hero-image img{width:100%;margin-left:auto;}
.trust-icon img{width:44px;height:44px;}
.service-card{position:relative;background:#fff;border-radius:var(--radius);box-shadow:0 0 4px rgba(0, 0, 0, .25);padding:8px 8px 12px;}
.service-image{height:180px;border-radius:var(--radius);overflow:hidden;}
.service-image img{width:100%;height:100%;object-fit:cover;}
.service-icon{width:50px;height:50px;display:flex;margin:-25px 0 0 12px;}
.service-icon img{width:50px;height:50px;position:relative;z-index:1;}
.service-content{padding:2px 12px 0;}
.service-content h3{font-family:var(--font-body);font-size:20px;line-height:1.6;font-weight:500;color:#333;}
.service-content p{color:#333;line-height:2;}
.service-content a{display:inline-flex;align-items:center;gap:4px;color:var(--blue);font-weight:500;line-height:2;margin-top:8px;}
.service-content a .service-link-arrow{width:24px;height:24px;flex:0 0 auto;}
.arts-story .container{position:relative;z-index:1;}
.story-image{position:relative;border-radius:var(--radius);overflow:hidden;margin:0;}
.story-image img{width:100%;height:492px;object-fit:cover;}
.story-image figcaption{position:absolute;bottom:4px;left:0;right:0;text-align:center;color:#fff;font-size:12px;}
.story-title{margin-bottom:20px;}
.arts-story h3{margin-bottom:12px;}
.arts-story p{line-height:1.75;margin-bottom:32px;}
.about-image{border-radius:var(--radius);overflow:hidden;}
.about-image img{width:100%;height:296px;object-fit:cover;}
.about-copy p{line-height:1.75;margin:22px 0 30px;}
.quote-card{margin:0;background:var(--blue);border-radius:var(--radius);height:296px;padding:80px 30px 20px;position:relative;overflow:hidden;}
.quote-card p{font-size:20px;line-height:1.6;font-weight:500;}
.quote-card cite{display:block;margin-top:18px;}
.quote-mark{position:absolute;left:20px;top:10px;width:60px;height:60px;}
.quote-art{position:absolute;right:15px;bottom:15px;width:97px;height:191px;}
.events .container{position:relative;z-index:1;}
.events h2{margin-bottom:40px;}
.event-image{border-radius:var(--radius);overflow:hidden;}
.event-image img{width:100%;height:341px;object-fit:cover;}
.demand h2{margin-bottom:24px;}
.check-list li{font-size:20px;font-weight:500;display:flex;align-items:center;gap:12px;}
.check-list li:before{content:"";width:24px;height:24px;background:url("https://res.cloudinary.com/cgibjxmm/image/upload/v1785921454/custom-cms/blue-checklist.png") center/contain no-repeat;flex:none;}
.faqs{padding-bottom:80px;}
.accordion{display:grid;gap:12px;}
.faq-item{background:var(--light);border-radius:var(--radius);overflow:hidden;}
.faq-item.active{background:#fff;box-shadow:0 0 4px rgba(0, 0, 0, .25);}
.faq-question{width:100%;border:0;background:transparent;display:flex;align-items:center;justify-content:space-between;gap:20px;padding:20px 20px 20px 40px;color:var(--heading);font-weight:500;font-size:20px;text-align:left;cursor:pointer;}
.faq-question img{width:40px;height:40px;flex:none;}
.faq-answer{display:none;padding:0 40px 30px;line-height:1.75;}
.faq-item.active .faq-answer{display:block;}
.media-grid figure{margin:0;text-align:center;}
.media-grid img, .media-grid iframe{display:block;width:100%;aspect-ratio:16/9;object-fit:cover;border:0;border-radius:var(--radius);}
.media-grid figcaption{font-size:24px;line-height:1.65;font-weight:500;color:var(--heading);margin-top:10px;}
.certifications{overflow:hidden;position:relative;}
.decorative-right-top:after{opacity:.12;top:0;bottom:auto;}
.cert-track{display:flex;align-items:center;gap:80px;width:max-content;transform:translateX(-110px);position:relative;z-index:1;}
.cert-track img{width:200px;height:200px;object-fit:contain;flex:none;}
.about.section-dark::before{width:600px;height:600px;left:-114px;top:-220px;background:rgba(224, 23, 131, .12);}
.about.section-dark::after{width:400px;height:400px;left:52.4%;right:auto;top:122px;background:rgba(119, 61, 190, .12);}
.certifications.decorative-right-top::after{width:400px;height:414px;top:0;right:0;bottom:auto;background-image:url("https://res.cloudinary.com/cgibjxmm/image/upload/v1785916220/custom-cms/hosting-event-background.png");opacity:1;transform:none;}
.cert-marquee{width:100%;overflow:hidden;position:relative;z-index:1;}
.cert-track{display:flex;align-items:center;gap:0;width:max-content;margin-left:-110px;transform:none;animation:certification-scroll 32s linear infinite;will-change:transform;}
.cert-group{display:flex;align-items:center;gap:80px;padding-right:80px;flex:0 0 auto;}
.cert-group img{width:200px;height:200px;object-fit:contain;flex:0 0 auto;}
@keyframes certification-scroll{from{transform:translate3d(0, 0, 0);}to{transform:translate3d(-50%, 0, 0);}}
.team-section{overflow:hidden;}
.team-section .section-heading{width:max-content;max-width:calc(100% - 30px);margin:0 auto 52px;text-align:center;}
.team-section .section-heading h2{display:block;}
.team-section .section-heading img.stroke-wide{width:155px;height:18px;margin:2px 0 0 auto!important;object-fit:contain;}
.team-pagination-wrap{width:100%;}
.team-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px;align-items:stretch;}
.team-card{min-width:0;height:100%;padding:8px;display:flex;flex-direction:column;background:var(--white);border-radius:var(--radius);box-shadow:0 0 4px rgba(0,0,0,.25);}
.team-card[hidden]{display:none!important;}
.team-card-image{width:100%;aspect-ratio:16/9;overflow:hidden;border-radius:var(--radius);background:#d9d9d9;}
.team-card-image img{width:100%;height:100%;object-fit:cover; margin: 0;}
.team-card-content{padding:14px 12px 20px;display:flex;flex:1;flex-direction:column;}
.team-card-header{margin-bottom:12px;}
.team-card h3{color:#333;font-family:var(--font-body);font-size:20px!important;line-height:1.6;font-weight:500;}
.team-role{color:var(--blue);line-height:1.6;font-weight:500;}
.team-description{color:#333;line-height:1.75;display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:5;overflow:hidden;}
.team-pagination{margin-top:32px;display:flex;align-items:center;justify-content:center;gap:10px;}
.team-pagination-pages{display:flex;align-items:center;justify-content:center;gap:8px;}
.team-pagination button{width:40px;height:40px;padding:0;display:grid;place-items:center;border:1px solid rgba(0,117,141,.35);border-radius:10px;background:var(--white);color:var(--blue);font:600 16px/1 var(--font-body);cursor:pointer;transition:background-color .2s ease,color .2s ease,border-color .2s ease,transform .2s ease;}
.team-pagination button:hover:not(:disabled),.team-pagination button:focus-visible{background:rgba(0,117,141,.08);border-color:var(--blue);outline:none;transform:translateY(-1px);}
.team-pagination button.is-active{background:var(--pink);border-color:var(--pink);color:var(--white);}
.team-pagination button:disabled{opacity:.35;cursor:not-allowed;transform:none;}
.team-pagination-arrow{font-size:24px!important;font-weight:400!important;}
.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0, 0, 0, 0);white-space:nowrap;border:0;}
.contact-banner .page-banner-art{width:614px;height:400px;opacity:.72;object-fit:contain;}
.contact-main{position:relative;overflow:hidden;}
.contact-main::before, .contact-main::after{content:"";position:absolute;pointer-events:none;background-repeat:no-repeat;background-position:center;background-size:contain;}
.contact-main::before{width:400px;height:414px;left:0;top:0;background-image:url("https://res.cloudinary.com/cgibjxmm/image/upload/v1785916220/custom-cms/hosting-event-background.png");}
.contact-main::after{width:259px;height:190px;right:0;bottom:0;background-image:url("https://res.cloudinary.com/cgibjxmm/image/upload/v1785928141/custom-cms/yoga-girl-background-2.png");}
.contact-main > .container{position:relative;z-index:1;}
.contact-feature-image{margin:0;height:697px;overflow:hidden;border-radius:var(--radius);}
.contact-feature-image img{width:100%;height:100%;object-fit:cover;}
.contact-column{display:grid;gap:20px;}
.contact-form-card, .contact-details-card{border-radius:var(--radius);background:#f5f5f5;}
.contact-form-card{padding:40px 32px;}
.contact-heading{margin-bottom:26px;}
.contact-heading img{width:108px;height:15px;margin-left:96px;}
.contact-intro{color:#3a3a3a;line-height:2;}
.contact-form{margin-top:28px;display:grid;gap:20px;}
.contact-name-grid{display:grid;grid-template-columns:repeat(2, minmax(0, 1fr));gap:20px;}
.form-field input, .form-field textarea{display:block;width:100%;padding:10px 20px;border:0;outline:0;border-radius:var(--radius);color:#3a3a3a;background:var(--white);font:400 16px/1.25 var(--font-body);}
.form-field textarea{height:40px;resize:vertical;overflow:hidden;}
.form-field input::placeholder, .form-field textarea::placeholder{color:#3a3a3a;opacity:1;}
.form-field input:focus, .form-field textarea:focus{box-shadow:0 0 0 2px rgba(0, 117, 141, .24);}
.contact-submit{border:0;width:max-content;cursor:pointer;}
.contact-details-card{padding:32px;display:grid;grid-template-columns:201px 1fr;align-items:center;gap:40px;}
.contact-detail{display:flex;align-items:center;gap:17px;color:#3a3a3a;}
.contact-detail-icon{width:44px;height:44px;flex:0 0 auto;}
.contact-detail-icon img{width:44px;height:44px;margin:0;}
.contact-detail-copy{display:grid;gap:4px;}
.contact-detail-copy small{color:#3a3a3a;font-size:16px;line-height:1.2;font-weight:600;}
.contact-detail-copy strong{color:#3a3a3a;font-size:20px;line-height:1.2;font-weight:600;white-space:nowrap;}
.teacher-banner .page-banner-art{width:614px;height:400px;opacity:.72;object-fit:contain;}
.teacher-intro-copy{color:#333;font-size:20px;line-height:1.6;font-weight:500;}
.ace-approved-card{padding:38px;display:grid;place-items:center;border-radius:var(--radius);background:#f5f5f5;}
.ace-approved-card img{width:308px;height:120px;object-fit:contain;}
.training-benefits{position:relative;overflow:hidden;}
.training-benefits::after{content:"";position:absolute;width:186px;height:186px;right:-14px;bottom:0;background:url("https://res.cloudinary.com/cgibjxmm/image/upload/v1785925760/custom-cms/yoga-girl-background-1.png") center/contain no-repeat;pointer-events:none;}
.training-benefits > .container{position:relative;z-index:1;}
.training-benefit-card{padding:40px;display:flex;flex-direction:column;background:var(--white);position:relative;overflow:hidden;}
.training-benefit-card-flower::after{content:"";position:absolute;width:120px;height:120px;right:0;top:0;background:url("https://res.cloudinary.com/cgibjxmm/image/upload/v1785925759/custom-cms/why-teach-pilates-flower.jpg") center/contain no-repeat;opacity:.7;pointer-events:none;}
.training-benefit-card .section-heading{margin-bottom:22px;position:relative;z-index:1;}
.training-benefit-card p{line-height:2;color:#333;position:relative;z-index:1;}
.training-benefit-image{width:100%;height:200px;margin-top:auto;border-radius:var(--radius);object-fit:cover;}
.training-modules{padding-top:100px;position:relative;}
.training-modules::before{width:400px;height:400px;left:-145px;top:26px;background:rgba(119, 61, 190, .12);}
.training-modules::after{width:600px;height:600px;right:-105px;top:71px;background:rgba(224, 23, 131, .12);}
.training-modules-heading{margin-bottom:58px;}
.training-modules-heading h2{margin-bottom:0;}
.training-modules-heading img.stroke-short{width:89px;height:16px;margin-left:185px;}
.training-modules-heading p{margin-top:12px;color:var(--white);line-height:2;}
.stroke-pink{filter:none;}
.module-list{display:grid;gap:20px;position:relative;z-index:1;}
.module-row{padding:19px 39px;display:grid;grid-template-columns:280px 1fr;align-items:center;gap:20px;border:1px solid #808080;border-radius:var(--radius);}
.module-label{height:80px;padding:0 26px;display:flex;align-items:center;justify-content:center;gap:12px;border-radius:var(--radius);background:var(--purple);color:var(--white);}
.module-label img{width:40px;height:40px;flex:0 0 auto;}
.module-label strong{font-size:20px;line-height:1.6;font-weight:500;white-space:nowrap;}
.module-row p{color:var(--white);line-height:1.875;}
.training-path-heading{margin-bottom:38px;}
.training-path-card{padding:32px;display:flex;flex-direction:column;position:relative;overflow:hidden;border-radius:var(--radius);background:var(--white);box-shadow:0 0 4px rgba(0, 0, 0, .25);}
.training-path-card::after{content:"";position:absolute;width:279px;height:120px;right:0;top:0;background-position:center;background-size:cover;background-repeat:no-repeat;pointer-events:none;}
.training-path-purple::after{background-image:url("https://res.cloudinary.com/cgibjxmm/image/upload/v1785925753/custom-cms/purple-smoke-background.jpg");}
.training-path-pink::after{background-image:url("https://res.cloudinary.com/cgibjxmm/image/upload/v1785925752/custom-cms/pink-smoke-background.jpg");}
.training-path-green::after{background-image:url("https://res.cloudinary.com/cgibjxmm/image/upload/v1785925751/custom-cms/green-smoke-background.jpg");}
.training-path-icon{width:80px;height:80px;margin:0 0 25px 0;position:relative;z-index:1;}
.training-path-card > p{margin-bottom:24px;display:flex;align-items:center;color:var(--heading);font-size:20px;line-height:1.6;font-weight:500;position:relative;z-index:1;}
.theme-btn-wide{width:100%;justify-content:space-between;margin-top:auto;position:relative;z-index:1;}
.training-details{padding-top:80px;padding-bottom:80px;}
.training-details::before{width:400px;height:400px;left:-139px;top:280px;background:rgba(119, 61, 190, .12);}
.training-details::after{width:600px;height:600px;right:-105px;top:71px;background:rgba(224, 23, 131, .12);}
.training-details-copy .section-heading{margin-bottom:20px;}
.training-details-copy .section-heading img.stroke-wide{width:225px;height:20px;}
.training-details-copy > p{line-height:2;color:var(--white);}
.training-feature-list{display:grid;gap:20px;}
.training-feature-card{padding:32px;display:grid;grid-template-columns:80px 1fr;align-items:center;gap:20px;border-radius:var(--radius);background:#1b2031;}
.training-feature-card img{width:80px;height:80px;}
