.training-benefit-card{padding:28px;}
.training-modules{padding-top:60px;}
.training-modules-heading img.stroke-short{margin-left:140px;}
.module-row{grid-template-columns:1fr;gap:16px;}
.module-label{width:100%;justify-content:flex-start;}
.training-path-grid, .training-faq-grid{grid-template-columns:1fr;}
.training-feature-card{grid-template-columns:70px 1fr;padding:24px;}
.training-feature-card img{width:70px;height:70px;}
.training-faq-item summary{padding:14px 16px 14px 20px;}
.training-faq-item summary img{width:34px;height:34px;}
.training-faq-answer{padding:0 20px 20px;}
.further-questions-image img{height:auto;}
.on-demand-action-row{gap:12px;}
.why-choose-demand{padding:60px 0;}
.why-choose-grid{grid-template-columns:120px 1fr;gap:28px;}
.why-choose-icon{width:120px;height:120px;}
.why-choose-divider{display:none;}
.why-choose-copy h2{margin-bottom:18px;}
.class-types-section::before{width:280px;height:290px;}
.class-type-item summary{padding:10px 14px 10px 18px;}
.class-type-label > img{width:46px;height:46px;}
.class-type-arrow{width:34px;height:34px;}
.class-type-answer{padding:0 18px 20px 76px;}
.studio-header{margin-bottom:34px;}
.studio-heading img{margin-left:58px;width:126px;}
.studio-address{font-size:17px;}
.studio-price-row{padding:22px;grid-template-columns:1fr;gap:14px;}
.studio-class-name{font-size:18px;align-items:flex-start;}
.studio-price-divider{width:100%;height:1px;background:linear-gradient(90deg, var(--blue) 0%, var(--pink) 50%, var(--purple) 100%);}
.studio-calendar{margin-top:50px;overflow-x:auto;}
.puppets-intro-image img{height:auto;}
.puppet-benefit-card{grid-template-columns:44px 1fr;gap:14px;padding:18px;}
.emily-heading{margin-bottom:38px;}
.emily-heading .section-heading img{margin-left:calc(50% + 90px);}
.emily-feature img, .emily-poster img{height:auto;}
.character-card > img{height:auto;}
.character-card-copy h2, .puppet-program-card h2, .large-puppet-card h2, .johnny-card h2{font-size:28px!important;}
.performance-card-grid{margin-top:40px;}
.puppet-contact-images img{height:auto;}
.puppet-program-card{padding:26px 18px;}
.puppet-program-card > img, .program-image-stack{margin-top:30px;}
.puppet-program-card > img, .program-image-stack img, .large-puppet-card > img, .johnny-card img{height:auto;}
.large-puppet-card{padding:26px 18px;}
.johnny-card{padding:26px 18px;}
.johnny-card h2{margin-bottom:28px;}
.puppets-stroke{width:180px;}
.emily-heading .section-heading .puppets-stroke{margin-left:calc(50% + 90px);}
.site-footer{padding: 60px 0 24px !important;}
}

@media(max-width:479px){
.section-heading.left img{margin-left:120px;width:110px;}
.theme-btn{font-size:14px;}
.trust-strip .container{gap:18px;}
.page-banner h1{font-size:38px!important;}
.page-banner p{line-height:1.6;}
.feature-cta-copy{flex-direction:column;}
h1{font-size:38px;}
.quote-card{padding:70px 22px 24px;}
.quote-card p{font-size:18px;}
.cert-track img{width:110px;height:110px;}
.cert-group img{width:110px;height:110px;}
.team-pagination{gap:7px;}
.team-pagination-pages{gap:6px;}
.team-pagination button{width:36px;height:36px;border-radius:9px;font-size:14px;}
.contact-form-card{padding:26px 20px;}
.contact-heading img{margin-left:62px;width:92px;}
.contact-intro{line-height:1.75;}
.form-field input, .form-field textarea{padding-inline:16px;}
.contact-detail-copy strong{font-size:18px;white-space:normal;overflow-wrap:anywhere;}
.ace-approved-card{padding:28px;}
.training-benefit-card{padding:22px;}
.training-benefit-card p, .module-row p, .training-feature-card p{line-height:1.75;}
.training-modules-heading img.stroke-short{margin-left:105px;}
.module-label strong{font-size:18px;}
.training-path-card{padding:24px;}
.training-feature-card{grid-template-columns:1fr;align-items:start;}
.training-feature-card img{width:64px;height:64px;}
.on-demand-action-row{flex-direction:column;align-items:stretch;}
.theme-btn-tall{width:100%;}
.why-choose-grid{grid-template-columns:1fr;}
.why-choose-icon{width:110px;height:110px;}
.class-type-answer{padding-left:18px;}
.studio-heading img{margin-left:45px;width:110px;}
.studio-address{align-items:flex-start;}
.studio-class-name img{width:46px;height:46px;}
.puppet-benefit-card{grid-template-columns:1fr;}
.puppet-benefit-card > img{width:44px;height:44px;}
.character-card-copy h3, .puppet-program-card h3{font-size:20px!important;}
.performance-info-card{padding:20px;}
.puppet-contact-images{grid-template-columns:1fr;}
.site-footer{padding: 40px 0 24px !important;}
}
